import inspect
from typing import Any, Callable


def function_has_argument(func: Callable[..., Any], arg_name: str) -> bool:
    """Returns whether or not the given function has a specific parameter"""
    sig = inspect.signature(func)
    return arg_name in sig.parameters

def functions_have_matching_signatures(
    func1: Callable[..., Any],
    func2: Callable[..., Any],
    excluded_params: set[str] = set()
) -> bool:
    """
    Checks if two functions have matching signatures, allowing for specific 
    parameters to be excluded from the check.
    """
    sig1 = inspect.signature(func1)
    sig2 = inspect.signature(func2)

    params1 = {
        name: param
        for name, param in sig1.parameters.items()
        if name not in excluded_params
    }
    params2 = {
        name: param
        for name, param in sig2.parameters.items()
        if name not in excluded_params
    }

    return params1 == params2

