    }

    msg1 = PyUString_FromString("), found (");
    if (!msg1) {
        Py_DECREF(msg);
        return 0;
    }

    for (j = 0; j < ndim; ++j) {
        expect_size = j != theaxis ? Xshape[j] : val;

        if (j == ndim - 1) {
            tmp = PyUString_FromFormat("%" NPY_INTP_FMT, expect_size);
            tmp1 = PyUString_FromFormat("%" NPY_INTP_FMT, Vishape[j]);
        } else {
            tmp = PyUString_FromFormat("%" NPY_INTP_FMT ",", expect_size);
            tmp1 = PyUString_FromFormat("%" NPY_INTP_FMT ",", Vishape[j]);
        }
        if (!tmp) {
            Py_DECREF(msg);
