        }
        if (!tmp1) {
            Py_DECREF(msg);
            Py_DECREF(msg1);
            Py_DECREF(tmp);
            return 0;
        }
        PyUString_ConcatAndDel(&msg, tmp);
        PyUString_ConcatAndDel(&msg1, tmp1);
    }
    tmp = PyUString_FromString(").");
    if (!tmp) {
        Py_DECREF(msg);
        Py_DECREF(msg1);
    }
    PyUString_ConcatAndDel(&msg1, tmp);
    PyUString_ConcatAndDel(&msg, msg1);
