#include "Imaging.h"

static inline UINT8
clip8(float in) {
    if (in <= 0.0) {
        return 0;
    }
    if (in >= 255.0) {
        return 255;
    }
    return (UINT8)in;
}

static inline INT32
clip32(float in) {
    if (in <= INT32_MIN) {
        return INT32_MIN;
    }
    if (in >= INT32_MAX) {
        return INT32_MAX;
    }
    return (INT32)in;
}

