                        memcpy(out + x * sizeof(v), &v, sizeof(v));
                    }
                }
                memcpy(out + x * sizeof(UINT32), in0 + x * sizeof(UINT32), sizeof(UINT32));
            }
        }
        memcpy(imOut->image[y], im->image[y], im->linesize);
    }
}

void
ImagingFilter5x5(Imaging imOut, Imaging im, const float *kernel, float offset) {
#define KERNEL1x5(in0, x, kernel, d)                                             \
    (_i2f((UINT8)in0[x - d - d]) * (kernel)[0] +                                 \
     _i2f((UINT8)in0[x - d]) * (kernel)[1] + _i2f((UINT8)in0[x]) * (kernel)[2] + \
     _i2f((UINT8)in0[x + d]) * (kernel)[3] +                                     \
     _i2f((UINT8)in0[x + d + d]) * (kernel)[4])

#define KERNEL1x5_32(in0, x, kernel, d)                                          \
    ((float)((INT32)in0[x - d - d]) * (kernel)[0] +                              \
     (float)((INT32)in0[x - d]) * (kernel)[1] + (float)((INT32)in0[x]) * (kernel)[2] + \
     (float)((INT32)in0[x + d]) * (kernel)[3] +                                  \
     (float)((INT32)in0[x + d + d]) * (kernel)[4])

    int x = 0, y = 0;

    if (im->image8) {
        memcpy(imOut->image[0], im->image[0], im->linesize);
        memcpy(imOut->image[1], im->image[1], im->linesize);
        if (im->bands == 1) {
            // Add one time for rounding
            float adj_offset = offset + 0.5;
            for (y = 2; y < im->ysize - 2; y++) {
                UINT8 *in_2 = (UINT8 *)im->image[y - 2];
                UINT8 *in_1 = (UINT8 *)im->image[y - 1];
                UINT8 *in0 = (UINT8 *)im->image[y];
                UINT8 *in1 = (UINT8 *)im->image[y + 1];
                UINT8 *in2 = (UINT8 *)im->image[y + 2];
                UINT8 *out = (UINT8 *)imOut->image[y];

                out[0] = in0[0];
                out[1] = in0[1];
                for (x = 2; x < im->xsize - 2; x++) {
                    float ss = adj_offset;
                    ss += KERNEL1x5(in2, x, &kernel[0], 1);
                    ss += KERNEL1x5(in1, x, &kernel[5], 1);
                    ss += KERNEL1x5(in0, x, &kernel[10], 1);
                    ss += KERNEL1x5(in_1, x, &kernel[15], 1);
                    ss += KERNEL1x5(in_2, x, &kernel[20], 1);
                    out[x] = clip8(ss);
                }
                out[x + 0] = in0[x + 0];
                out[x + 1] = in0[x + 1];
            }
        } else {
            // Add one time for rounding
            float adj_offset = offset + 0.5;
            for (y = 2; y < im->ysize - 2; y++) {
                UINT8 *in_2 = (UINT8 *)im->image[y - 2];
                UINT8 *in_1 = (UINT8 *)im->image[y - 1];
                UINT8 *in0 = (UINT8 *)im->image[y];
                UINT8 *in1 = (UINT8 *)im->image[y + 1];
                UINT8 *in2 = (UINT8 *)im->image[y + 2];
                UINT8 *out = (UINT8 *)imOut->image[y];

                memcpy(out, in0, sizeof(UINT32) * 2);
                if (im->bands == 2) {
                    for (x = 2; x < im->xsize - 2; x++) {
                        float ss0 = adj_offset;
                        float ss3 = adj_offset;
                        UINT32 v;
                        ss0 += KERNEL1x5(in2, x * 4 + 0, &kernel[0], 4);
                        ss3 += KERNEL1x5(in2, x * 4 + 3, &kernel[0], 4);
                        ss0 += KERNEL1x5(in1, x * 4 + 0, &kernel[5], 4);
                        ss3 += KERNEL1x5(in1, x * 4 + 3, &kernel[5], 4);
                        ss0 += KERNEL1x5(in0, x * 4 + 0, &kernel[10], 4);
                        ss3 += KERNEL1x5(in0, x * 4 + 3, &kernel[10], 4);
                        ss0 += KERNEL1x5(in_1, x * 4 + 0, &kernel[15], 4);
                        ss3 += KERNEL1x5(in_1, x * 4 + 3, &kernel[15], 4);
                        ss0 += KERNEL1x5(in_2, x * 4 + 0, &kernel[20], 4);
                        ss3 += KERNEL1x5(in_2, x * 4 + 3, &kernel[20], 4);
                        v = MAKE_UINT32(clip8(ss0), 0, 0, clip8(ss3));
                        memcpy(out + x * sizeof(v), &v, sizeof(v));
                    }
                } else if (im->bands == 3) {
                    for (x = 2; x < im->xsize - 2; x++) {
                        float ss0 = adj_offset;
                        float ss1 = adj_offset;
                        float ss2 = adj_offset;
                        UINT32 v;
                        ss0 += KERNEL1x5(in2, x * 4 + 0, &kernel[0], 4);
                        ss1 += KERNEL1x5(in2, x * 4 + 1, &kernel[0], 4);
                        ss2 += KERNEL1x5(in2, x * 4 + 2, &kernel[0], 4);
                        ss0 += KERNEL1x5(in1, x * 4 + 0, &kernel[5], 4);
                        ss1 += KERNEL1x5(in1, x * 4 + 1, &kernel[5], 4);
                        ss2 += KERNEL1x5(in1, x * 4 + 2, &kernel[5], 4);
                        ss0 += KERNEL1x5(in0, x * 4 + 0, &kernel[10], 4);
                        ss1 += KERNEL1x5(in0, x * 4 + 1, &kernel[10], 4);
                        ss2 += KERNEL1x5(in0, x * 4 + 2, &kernel[10], 4);
                        ss0 += KERNEL1x5(in_1, x * 4 + 0, &kernel[15], 4);
                        ss1 += KERNEL1x5(in_1, x * 4 + 1, &kernel[15], 4);
                        ss2 += KERNEL1x5(in_1, x * 4 + 2, &kernel[15], 4);
                        ss0 += KERNEL1x5(in_2, x * 4 + 0, &kernel[20], 4);
                        ss1 += KERNEL1x5(in_2, x * 4 + 1, &kernel[20], 4);
                        ss2 += KERNEL1x5(in_2, x * 4 + 2, &kernel[20], 4);
                        v = MAKE_UINT32(clip8(ss0), clip8(ss1), clip8(ss2), 0);
                        memcpy(out + x * sizeof(v), &v, sizeof(v));
                    }
                } else if (im->bands == 4) {
                    for (x = 2; x < im->xsize - 2; x++) {
                        float ss0 = adj_offset;
                        float ss1 = adj_offset;
                        float ss2 = adj_offset;
                        float ss3 = adj_offset;
                        UINT32 v;
                        ss0 += KERNEL1x5(in2, x * 4 + 0, &kernel[0], 4);
                        ss1 += KERNEL1x5(in2, x * 4 + 1, &kernel[0], 4);
                        ss2 += KERNEL1x5(in2, x * 4 + 2, &kernel[0], 4);
                        ss3 += KERNEL1x5(in2, x * 4 + 3, &kernel[0], 4);
                        ss0 += KERNEL1x5(in1, x * 4 + 0, &kernel[5], 4);
                        ss1 += KERNEL1x5(in1, x * 4 + 1, &kernel[5], 4);
                        ss2 += KERNEL1x5(in1, x * 4 + 2, &kernel[5], 4);
                        ss3 += KERNEL1x5(in1, x * 4 + 3, &kernel[5], 4);
                        ss0 += KERNEL1x5(in0, x * 4 + 0, &kernel[10], 4);
                        ss1 += KERNEL1x5(in0, x * 4 + 1, &kernel[10], 4);
                        ss2 += KERNEL1x5(in0, x * 4 + 2, &kernel[10], 4);
                        ss3 += KERNEL1x5(in0, x * 4 + 3, &kernel[10], 4);
                        ss0 += KERNEL1x5(in_1, x * 4 + 0, &kernel[15], 4);
                        ss1 += KERNEL1x5(in_1, x * 4 + 1, &kernel[15], 4);
                        ss2 += KERNEL1x5(in_1, x * 4 + 2, &kernel[15], 4);
                        ss3 += KERNEL1x5(in_1, x * 4 + 3, &kernel[15], 4);
                        ss0 += KERNEL1x5(in_2, x * 4 + 0, &kernel[20], 4);
                        ss1 += KERNEL1x5(in_2, x * 4 + 1, &kernel[20], 4);
                        ss2 += KERNEL1x5(in_2, x * 4 + 2, &kernel[20], 4);
                        ss3 += KERNEL1x5(in_2, x * 4 + 3, &kernel[20], 4);
                        v = MAKE_UINT32(clip8(ss0), clip8(ss1), clip8(ss2), clip8(ss3));
                        memcpy(out + x * sizeof(v), &v, sizeof(v));
                    }
                }
                memcpy(
                    out + x * sizeof(UINT32), in0 + x * sizeof(UINT32), sizeof(UINT32) * 2);
            }
        }
        memcpy(imOut->image[y], im->image[y], im->linesize);
        memcpy(imOut->image[y + 1], im->image[y + 1], im->linesize);
    } else if (im->image32) {
        memcpy(imOut->image[0], im->image[0], im->linesize);
        memcpy(imOut->image[1], im->image[1], im->linesize);
        if (im->bands == 1) {
            float adj_offset = offset + 0.5;
            for (y = 2; y < im->ysize - 2; y++) {
                INT32 *in_2 = (INT32 *)im->image[y - 2];
                INT32 *in_1 = (INT32 *)im->image[y - 1];
                INT32 *in0 = (INT32 *)im->image[y];
                INT32 *in1 = (INT32 *)im->image[y + 1];
                INT32 *in2 = (INT32 *)im->image[y + 2];
                INT32 *out = (INT32 *)imOut->image[y];

                out[0] = in0[0];
                out[1] = in0[1];
                for (x = 2; x < im->xsize - 2; x++) {
                    float ss = adj_offset;
                    ss += KERNEL1x5_32(in2, x, &kernel[0], 1);
                    ss += KERNEL1x5_32(in1, x, &kernel[5], 1);
                    ss += KERNEL1x5_32(in0, x, &kernel[10], 1);
                    ss += KERNEL1x5_32(in_1, x, &kernel[15], 1);
                    ss += KERNEL1x5_32(in_2, x, &kernel[20], 1);
                    out[x] = clip32(ss);
                }
                out[x + 0] = in0[x + 0];
                out[x + 1] = in0[x + 1];
            }
        } else {
            float adj_offset = offset + 0.5;
            for (y = 2; y < im->ysize - 2; y++) {
                INT32 *in_2 = (INT32 *)im->image[y - 2];
                INT32 *in_1 = (INT32 *)im->image[y - 1];
                INT32 *in0 = (INT32 *)im->image[y];
                INT32 *in1 = (INT32 *)im->image[y + 1];
                INT32 *in2 = (INT32 *)im->image[y + 2];
                INT32 *out = (INT32 *)imOut->image[y];

                memcpy(out, in0, sizeof(UINT32) * 2);
                if (im->bands == 2) {
                    for (x = 2; x < im->xsize - 2; x++) {
                        float ss0 = adj_offset;
                        float ss3 = adj_offset;
                        UINT32 v;
                        ss0 += KERNEL1x5_32(in2, x * 4 + 0, &kernel[0], 4);
                        ss3 += KERNEL1x5_32(in2, x * 4 + 3, &kernel[0], 4);
                        ss0 += KERNEL1x5_32(in1, x * 4 + 0, &kernel[5], 4);
                        ss3 += KERNEL1x5_32(in1, x * 4 + 3, &kernel[5], 4);
                        ss0 += KERNEL1x5_32(in0, x * 4 + 0, &kernel[10], 4);
                        ss3 += KERNEL1x5_32(in0, x * 4 + 3, &kernel[10], 4);
                        ss0 += KERNEL1x5_32(in_1, x * 4 + 0, &kernel[15], 4);
                        ss3 += KERNEL1x5_32(in_1, x * 4 + 3, &kernel[15], 4);
                        ss0 += KERNEL1x5_32(in_2, x * 4 + 0, &kernel[20], 4);
                        ss3 += KERNEL1x5_32(in_2, x * 4 + 3, &kernel[20], 4);
                        v = MAKE_UINT32(clip32(ss0), 0, 0, clip32(ss3));
                        memcpy(out + x * sizeof(v), &v, sizeof(v));
                    }
                } else if (im->bands == 3) {
                    for (x = 2; x < im->xsize - 2; x++) {
                        float ss0 = adj_offset;
                        float ss1 = adj_offset;
                        float ss2 = adj_offset;
                        UINT32 v;
                        ss0 += KERNEL1x5_32(in2, x * 4 + 0, &kernel[0], 4);
                        ss1 += KERNEL1x5_32(in2, x * 4 + 1, &kernel[0], 4);
                        ss2 += KERNEL1x5_32(in2, x * 4 + 2, &kernel[0], 4);
                        ss0 += KERNEL1x5_32(in1, x * 4 + 0, &kernel[5], 4);
                        ss1 += KERNEL1x5_32(in1, x * 4 + 1, &kernel[5], 4);
                        ss2 += KERNEL1x5_32(in1, x * 4 + 2, &kernel[5], 4);
                        ss0 += KERNEL1x5_32(in0, x * 4 + 0, &kernel[10], 4);
                        ss1 += KERNEL1x5_32(in0, x * 4 + 1, &kernel[10], 4);
                        ss2 += KERNEL1x5_32(in0, x * 4 + 2, &kernel[10], 4);
                        ss0 += KERNEL1x5_32(in_1, x * 4 + 0, &kernel[15], 4);
                        ss1 += KERNEL1x5_32(in_1, x * 4 + 1, &kernel[15], 4);
                        ss2 += KERNEL1x5_32(in_1, x * 4 + 2, &kernel[15], 4);
                        ss0 += KERNEL1x5_32(in_2, x * 4 + 0, &kernel[20], 4);
                        ss1 += KERNEL1x5_32(in_2, x * 4 + 1, &kernel[20], 4);
                        ss2 += KERNEL1x5_32(in_2, x * 4 + 2, &kernel[20], 4);
                        v = MAKE_UINT32(clip32(ss0), clip32(ss1), clip32(ss2), 0);
                        memcpy(out + x * sizeof(v), &v, sizeof(v));
                    }
                } else if (im->bands == 4) {
                    for (x = 2; x < im->xsize - 2; x++) {
                        float ss0 = adj_offset;
                        float ss1 = adj_offset;
                        float ss2 = adj_offset;
                        float ss3 = adj_offset;
                        UINT32 v;
                        ss0 += KERNEL1x5_32(in2, x * 4 + 0, &kernel[0], 4);
                        ss1 += KERNEL1x5_32(in2, x * 4 + 1, &kernel[0], 4);
                        ss2 += KERNEL1x5_32(in2, x * 4 + 2, &kernel[0], 4);
                        ss3 += KERNEL1x5_32(in2, x * 4 + 3, &kernel[0], 4);
                        ss0 += KERNEL1x5_32(in1, x * 4 + 0, &kernel[5], 4);
                        ss1 += KERNEL1x5_32(in1, x * 4 + 1, &kernel[5], 4);
                        ss2 += KERNEL1x5_32(in1, x * 4 + 2, &kernel[5], 4);
                        ss3 += KERNEL1x5_32(in1, x * 4 + 3, &kernel[5], 4);
                        ss0 += KERNEL1x5_32(in0, x * 4 + 0, &kernel[10], 4);
                        ss1 += KERNEL1x5_32(in0, x * 4 + 1, &kernel[10], 4);
                        ss2 += KERNEL1x5_32(in0, x * 4 + 2, &kernel[10], 4);
                        ss3 += KERNEL1x5_32(in0, x * 4 + 3, &kernel[10], 4);
                        ss0 += KERNEL1x5_32(in_1, x * 4 + 0, &kernel[15], 4);
                        ss1 += KERNEL1x5_32(in_1, x * 4 + 1, &kernel[15], 4);
                        ss2 += KERNEL1x5_32(in_1, x * 4 + 2, &kernel[15], 4);
                        ss3 += KERNEL1x5_32(in_1, x * 4 + 3, &kernel[15], 4);
                        ss0 += KERNEL1x5_32(in_2, x * 4 + 0, &kernel[20], 4);
                        ss1 += KERNEL1x5_32(in_2, x * 4 + 1, &kernel[20], 4);
                        ss2 += KERNEL1x5_32(in_2, x * 4 + 2, &kernel[20], 4);
                        ss3 += KERNEL1x5_32(in_2, x * 4 + 3, &kernel[20], 4);
                        v = MAKE_UINT32(clip32(ss0), clip32(ss1), clip32(ss2), clip32(ss3));
                        memcpy(out + x * sizeof(v), &v, sizeof(v));
                    }
                }
                memcpy(
                    out + x * sizeof(UINT32), in0 + x * sizeof(UINT32), sizeof(UINT32) * 2);
            }
        }
        memcpy(imOut->image[y], im->image[y], im->linesize);
        memcpy(imOut->image[y + 1], im->image[y + 1], im->linesize);
    }
}

Imaging
ImagingFilter(Imaging im, int xsize, int ysize, const FLOAT32 *kernel, FLOAT32 offset) {
    Imaging imOut;
    ImagingSectionCookie cookie;

    if (!im || (im->type != IMAGING_TYPE_UINT8 && im->type != IMAGING_TYPE_INT32)) {
        return (Imaging)ImagingError_ModeError();
    }

    if (im->xsize < xsize || im->ysize < ysize) {
        return ImagingCopy(im);
    }

    if ((xsize != 3 && xsize != 5) || xsize != ysize) {
        return (Imaging)ImagingError_ValueError("bad kernel size");
    }

    imOut = ImagingNewDirty(im->mode, im->xsize, im->ysize);
    if (!imOut) {
        return NULL;
    }

    ImagingSectionEnter(&cookie);
    if (xsize == 3) {
        /* 3x3 kernel. */
        ImagingFilter3x3(imOut, im, kernel, offset);
    } else {
        /* 5x5 kernel. */
        ImagingFilter5x5(imOut, im, kernel, offset);
    }
    ImagingSectionLeave(&cookie);
    return imOut;
}

